# -*- coding: utf-8 -*-
from lib import C, N

PAPER = lambda nxt: [C("Do the paper version: dated, copied, filed", nxt, cash=-5, flags=["paperTrail"], hidden="Dated documentation added to the case record", note="Another dated page joins the folder."),
                     C("Handle it with a conversation and move on", nxt, note="Conversations end. The file keeps what it was given.")]

# ---------------- S134 — Complex ----------------
S134 = dict(
 num=134, name="The Appeal Beside the Case", tier="Complex",
 startDateISO="2026-02-02", startCash=180,
 summary="An indicated report from a workplace-adjacent incident runs beside the dependency case of the man's daughter. Two proceedings, two burdens, two buildings — and a superintendent's logbook with two phone calls in it that the summary never mentions.",
 contentNote="This scenario depicts an indicated-report appeal proceeding alongside a dependency case. There is no graphic content. Players may skip any scene or use the quick exit at any time.",
 offsetNote=" (the appeal notice date)",
 win_id="end_dual",
 nodes=[
  N("start",0,"The Boiler Room and the Letter",[
    "Your name is Hollis. You keep the boilers running at a school across town from the one your daughter Fern, six, attends — a fact the investigation never quite kept straight. The Saturday the furnace failed at your building, you brought Fern to your sister's, then to the boiler room for forty minutes with her tablet and a chair by the door while you and the super, Mr. Halloran, coaxed the plant back to life.",
    "The report that followed says a child was left unsupervised in an industrial space. The dependency petition says the home needs services. And on Monday, February 2, 2026, the indicated notice arrives with its 90-day window (23 Pa.C.S. § 6341(a)(2)) — closing Sunday, May 3, 2026 — stapled, in your mind, to a case file that is not the same file. Two proceedings now run beside each other. They will be decided by different people, under different burdens, from different paper. Confusing them is the first way to lose both."],
    [C("Draw two columns on one page: APPEAL and CASE, each with its own clock","two_files",flags=["columnsDrawn"],hidden="Two-proceeding board drawn with separate clocks",note="Two files, two columns, no bleeding ink between them."),
     C("It's one problem with two envelopes — treat it as one","two_files",note="The envelopes disagree with you, and they get a vote.")]),
  N("two_files",3,"Ms. Adeyemi Separates the Burdens",[
    "Your lawyer, Ms. Adeyemi — counsel being your right in the dependency case (42 Pa.C.S. § 6337) — draws the distinction the year will run on: 'In the appeal, the agency must prove its report by substantial evidence (23 Pa.C.S. § 6341(c.2)(5)). In the case, the court asks what Fern needs and whether the plan is working. Different questions. Different evidence. The same man, unfortunately for your calendar.'",
    "She is blunt about sequencing: the appeal's window closes May 3 and cannot be reopened; the case's reviews can be continued. 'Perishable first,' she says, 'in this family as in all families.'"],
    PAPER("appeal_week")),
  N("appeal_week",6,"Appeal Week",[
    "The appeal letter is the library's half-page: name, report number, amend or expunge. It feels — as it always feels — too small to hold a man's working life, his clearances for every school building in the district riding on a registry he has never seen.",
    "Your sister, who kept Fern that Saturday until the boiler room, watches you seal it and asks the practical question: 'And the case?' Both, you tell her. In order. The appeal this week because it expires; the case every week because it matters."],
    [C("Mail the appeal this week, stamped copy filed, clocks calendared","appeal_filed134",cash=-10,flags=["appealFiled"],hidden="Indicated-report appeal filed in the first week of the window",note="Day 10 of 90. The perishable is preserved."),
     C("Focus on the case first — the appeal can wait until the spring review settles","end_case_only",note="It cannot, and this is where that discovery gets made, at leisure, in May.")]),
  N("appeal_filed134",10,"Filed, and the Case Goes On",[
    "With the appeal docketed, the case resumes its own rhythm: Fern is home under the plan — this case never took her, a fact worth remembering when the two files blur at 2 a.m. — with services, a safety plan for work emergencies, and reviews on the court's calendar, not the Bureau's.",
    "The safety plan's coverage roster is your sister, the super's wife (a retired aide), and the neighbor — the Saturday problem answered in advance, in signatures."],
    [C("Build the work-emergency roster in signatures and file it with the plan","records134",cash=-5,flags=["rosterSigned"],hidden="Work-emergency coverage roster signed and filed",note="The Saturday that started this now has a documented answer for every future Saturday."),
     C("Everyone knows the arrangement — signatures are bureaucracy","records134",note="Bureaucracy is the genre the plan is published in. Sign it.")]),
  N("records134",20,"The Record, Requested",[
    "You request the case record in writing (55 Pa. Code § 3130.44(d)) — the dependency mirror — and, in the same week, note what the appeal will separately compel: the investigation evidence itself, under the appeal's own rule. Two mirrors, two buildings, two requests.",
    "What the case record holds is mostly fair. What matters is a cross-reference in the investigation summary: 'see facilities log, Saturday.' A log you did not know had been consulted. Logs have authors. Authors can be asked for copies."],
    [C("Request the facilities log through counsel, in writing, this week","logbook",cash=-5,flags=["recordsRequested"],hidden="Dependency record requested under § 3130.44(d); facilities log requested",note="The summary cited a document. Documents can be summoned."),
     C("The log is the school's business — leave it to the lawyers' timeline","logbook",note="It is now your business; it was cited against you. Timelines, however, are how citations retire.")]),
  N("logbook",34,"Two Phone Calls",[
    "The superintendent's logbook page for that Saturday is a clerk's masterpiece of indifference: furnace alarm 8:51; Halloran on site 9:02; 'called H. — daughter with sister, ETA agreed' — your call to the super at 9:04, arranging Fern's coverage before the boiler room; and at 11:47, 'H. called — leaving, sister has girl.' Two calls. Both logged. Neither in the summary.",
    "The summary's version — a child left in an industrial space — required those two calls not to exist. They exist in a spiral notebook in a facilities office, in handwriting, with times. This is the appeal's spine, and it was never hidden. It was merely never asked for."],
    [C("Index the logbook page as the appeal's centerpiece, copy filed in both tracks","intake_note",flags=["logbookFiled"],hidden="Superintendent's logbook page obtained and filed in both tracks",note="9:04 and 11:47. The whole appeal will hang on two times a clerk wrote down without caring."),
     C("Keep the logbook for the hearing — let them commit to the summary first","intake_note",note="They already committed, in writing, months ago. Filed paper testifies longer than surprises.")]),
  N("intake_note",48,"The Intake Note's Own Correction",[
    "The investigation's intake note — obtained with the appeal's evidence packet, which the agency must provide, including the potentially exculpatory, within ten days of the scheduling order (23 Pa.C.S. § 6341(c.2)(4)) — contains the report's first form: 'child at father's workplace, supervised by father and super, per caller.'",
    "Somewhere between the intake note and the indicated summary, 'supervised by father and super' became 'left unsupervised.' The packet contains no document explaining the journey. Bureau hearings are where such journeys get explained, on the record, by their authors."],
    [C("Build the exhibit set: intake note, logbook, summary — the journey, in three pages","correction_addendum",flags=["evidenceReceived"],hidden="Intake note obtained under § 6341(c.2)(4); exhibit set built",note="Three pages, one disappearance. The hearing will ask where the supervision went."),
     C("Your testimony can walk the officer through the difference","correction_addendum",note="Testimony walks; exhibits stand still and get quoted. Build the standing kind.")]),
  N("correction_addendum",62,"The Agency Corrects Itself",[
    "Spring brings the document you did not request and will never give back: the agency's correction addendum to the investigation file, noting that the logbook 'was reviewed subsequent to the summary' and that the summary 'should be read with' the log. Bureaucratese, translated: the paper trail now contradicts the summary inside the agency's own file.",
    "Ms. Adeyemi labels it Exhibit 1. 'Not the logbook,' she says. 'The addendum. Anybody can keep a log. An agency correcting itself is the rarest exhibit in the building.'"],
    [C("Make the addendum Exhibit 1 and the logbook Exhibit 2 — their correction leads","spring_review134",flags=["addendumFiled"],hidden="Agency correction addendum obtained and made Exhibit 1",note="Their own file, correcting their own summary. The burden is about to get heavy — for its owner."),
     C("Lead with the logbook — it's the most human document","spring_review134",note="Human loses to official inside official buildings. The addendum is the agency's white flag in its own handwriting.")]),
  N("spring_review134",76,"The Case's Spring Review",[
    "The dependency review, in its own building on its own clock, reads the plan's ordinary excellence: services attended, roster signed and once used (a February furnace, a documented Saturday), Fern thriving in the first grade two streets from your sister's.",
    "The judge asks about the 'other matter' and Ms. Adeyemi answers in the formula the two-column board made possible: 'Litigating in its own forum, on its own clock, Your Honor. Ahead of schedule in both.' The review continues the case toward a fall closing review — the tracks converging, at last, on a season instead of a collision."],
    PAPER("exhibit_one")),
  N("exhibit_one",90,"Exhibit One, Framed",[
    "The appeal packet is assembled the way the library's packets are: exhibits numbered, the addendum first, a one-page chronology signed by you and the super both — his signature obtained with a visit, a copy of his own logbook page, and the observation that clerks' handwriting has ended more arguments than lawyers'.",
    "He signs with the air of a man whose record-keeping has been vindicated by history, which it has."],
    [C("File the packet with the Bureau and a copy in the case record","bureau_prep",cash=-10,flags=["appealPacket"],hidden="Appeal packet filed with the correction addendum as Exhibit 1",note="Filed in both buildings. Corridors walked. The hearing is now a reading."),
     C("File with the Bureau only — the case file doesn't need appeal paper","bureau_prep",note="It needs exactly this paper; the fall review will ask what the Bureau decided and why.")]),
  N("bureau_prep",130,"June's Quiet Work",[
    "June is the corridor month: the hearing set for Friday, July 10, 2026; the case's services completing on schedule; Fern's school year ending with a folder of first-grade evidence that no proceeding requested and the family keeps anyway.",
    "Preparation is the library's June liturgy: the likely questions, each answered by an exhibit before it is answered by a voice; the closing, drafted short; the burden, memorized — theirs, substantial evidence, § 6341(c.2)(5)."],
    [C("Prepare the closing around three exhibits and one standard","bureau134",flags=["closingReady"],hidden="Hearing preparation completed against the exhibit set",note="Three exhibits, one standard, no adjectives. Ready."),
     C("Prepare to tell the whole Saturday, start to finish","bureau134",note="Whole Saturdays are how witnesses wander. The exhibits tell it; you confirm it.")]),
  N("bureau134",158,"Friday, July 10",[
    "The hearing officer opens the agency's file and finds its own correction filed as the appellant's first exhibit — a geometry no cross-examination can straighten. The agency's witness walks the journey from intake note to summary and cannot produce the page where the supervision went.",
    "The super testifies for eleven minutes, mostly about handwriting. The logbook's times — 9:04, 11:47 — enter the transcript through the least dramatic witness in the building's history, which is precisely their power."],
    [C("Close on the burden and the addendum: their standard, their file, their correction","decision134",note="The closing writes itself; you just read the file back to its owners."),
     C("Close on your credibility — a father's word against a summary","end_split134",note="Credibility contests are coin flips the burdened side loves. The paper was the case; abandoning it at the closing table loses what the exhibits won.")]),
  N("decision134",189,"Day 31",[
    "The decision — inside the 45 days the rule allows (23 Pa.C.S. § 6341(c.3)) — amends the report to unfounded. The registry releases its hold on your clearances; the district's facilities office gets its boiler man back without an asterisk.",
    "Ms. Adeyemi's caution arrives with the champagne of the moment still unopened: 'The appeal is won. The case is not the appeal. The fall review closes the case, and it will read what we file this fall — not what the Bureau decided.' Two columns, to the very end."],
    [C("File the expungement in the dependency record the same week","corridor_last",flags=["expungementFiled"],hidden="Expungement order filed in the dependency case record",note="The corridor, walked one last time. Paper does not travel alone."),
     C("The court will learn the outcome through channels","corridor_last",note="Channels summarize. File the order.")]),
  N("corridor_last",191,"The Corridor, Walked Last",[
    "The stamp lands. The dependency file now contains the Bureau's answer in full — the fall review's reader will meet the expungement as a document, not a rumor, and will meet Exhibit 1's lesson with it: this family's paper was checked against its sources and held.",
    "What remains is the fall packet: the case's own closing argument, built the case's way — services, roster, school, the plan's completion in dates."],
    PAPER("fall_a")),
  N("fall_a",195,"Services, Complete",[
    "The plan's services complete in September with certificates filed on their dates — the parenting course, the safety-planning series, the home assessment's final visit signed off with a note about the Saturday shelf of labeled emergency supplies that made the assessor laugh, once, in writing.",
    "Laughter in an assessment note is filed like anything else. It testifies."],
    [C("Index the completions into the fall packet as they land","fall_prep134",flags=["servicesDone"],hidden="Plan services completed and indexed",note="Completion, dated, indexed. The packet assembles itself from the year's habits."),
     C("Certificates can be gathered at the end — that's what packets are","fall_prep134",note="Gathered-at-the-end is how certificates become 'to be provided.' Index as they land.")]),
  N("fall_prep134",205,"The Fall Packet",[
    "The fall packet mirrors the appeal packet's discipline in the case's own dialect: chronology first, completions second, the roster and its one documented use third, the expungement order where the judge will meet it without asking.",
    "It is, in form, the same book as July's, translated: in the appeal, the agency's paper defeated the agency's summary; here, the family's paper simply is the family's summary — accurate because it was assembled monthly, not remembered in October."],
    [C("File the fall packet two weeks before the closing review","fall_b",cash=-10,flags=["fallPacket"],hidden="Fall closing packet assembled and filed early",note="Early, indexed, complete. The review is now a reading."),
     C("File it the week of the review — fresher facts","fall_b",note="Facts don't freshen in folders. They just arrive late to the judge's reading.")]),
  N("fall_b",210,"Ms. Adeyemi's Last Distinction",[
    "Over coffee she draws the two columns a final time and writes the year's lesson under both: the appeal was won by the agency's paper; the case will be closed by yours. 'People think these proceedings are about what happened,' she says. 'They are about what the file can prove happened, on the day somebody reads it.'",
    "Fern, informed that the fall talking day is the last one, requests that her tablet be charged for it. Logistics of hope, handled."],
    [C("Prepare your statement to match the packet, date for date","fall_c",flags=["statementReady"],hidden="Closing statement prepared against the fall packet",note="The witness and the book, agreeing. The year's last rehearsal."),
     C("Prepare to finally say everything the year felt like","fall_c",note="The year felt like paper. Say the packet.")]),
  N("fall_c",215,"The Sister's Page",[
    "Your sister's one-page statement — the Saturdays, the roster, the February furnace executed exactly as signed — is the fall packet's final document, filed last because it was earned latest: the family's own addendum, correcting nothing, confirming everything.",
    "She signs it at the boiler room door, where this began, with the super's pen. The building's stationery has a sense of humor, or history does."],
    [C("File her statement and close the packet","fall_review134",flags=["sisterFiled"],hidden="Sister's corroborating statement filed",note="The packet closes the way the case opened: family, documented, on time."),
     C("Her statement can be summarized in yours","fall_review134",note="Summaries are how sisters become hearsay. File the page.")]),
  N("fall_review134",228,"The Closing Review",[
    "The fall review reads the year in twenty minutes. The expungement is in the file where you filed it; the completions are dated; the roster has its Saturday; the judge's questions are the questions the packet already answered, asked aloud so the record can hear them answered.",
    "Ms. Adeyemi states the ask the two columns were built for: closure of the case, the expungement noted, the family's paper complete in both proceedings."],
    [C("Ask for closure today, both proceedings complete, the record as filed","end_dual",req=["appealFiled","recordsRequested","fallPacket"],note="Two columns, both closed. The board comes off the wall."),
     C("Ask for one more review to be safe — the file is strong","end_dual",note="Strong files close. Extra reviews are how open cases collect new summaries."),
     C("Thank the court and let it craft the order","decision134",note="Loops back through courtesy into another season of openness. Propose the ending the paper earned.")]),
  N("end_dual",235,"Both Columns Closed",[
    "The case closes at the fall review; the registry had already released you in August. You take the two-column page off the refrigerator and file it — where else — as the folder's last document, behind two closing orders that between them say the whole thing: unfounded, and closed.",
    "Fern's school and yours both get their boiler-adjacent family back without annotation. The super asks, at the winter furnace check, whether you kept the logbook page. You did. Clerks' handwriting, framed by events, tends to get kept."],
    ending=True, debrief=[
      "THE TWO PROCEEDINGS, AUDITED — Appeal: notified Monday, February 2, 2026; 90 days → Sunday, May 3, 2026 (23 Pa.C.S. § 6341(a)(2)); filed day 10. Evidence under § 6341(c.2)(4) produced the intake note; the record request (55 Pa. Code § 3130.44(d)) produced the logbook lead; the agency's burden (c.2)(5) failed against its own correction addendum; decision on day 31 of (c.3)'s 45. Case: services, roster, reviews, and a fall packet — closed on the family's paper, a season after the registry let go.",
      "WHY THE WIN REQUIRED TWO TRACKS — Neither proceeding could win the other. The dependency court never adjudicates the registry; the Bureau never closes a case. The capstone discipline was separation with a corridor: distinct burdens, distinct packets, and every decision physically carried into the other file. The gated route required **appealFiled**, **recordsRequested**, and **fallPacket** — the perishable filed, the mirror requested, and the closing book actually built.",
      "WHAT NO STRATEGY CONTROLS — A hearing officer, a superintendent's record-keeping habits, and a furnace. The route controlled the separation of the burdens and the summoning of the documents: the logbook existed all along, which is the scenario's whole thesis — decisive paper is usually already written, by someone else, waiting to be asked for."]),
  N("end_split134",189,"Expunged in One Building",[
    "In this branch the appeal is lost on credibility's coin flip — or the case is closed while the registry keeps its word — and the two columns close a season apart, one family's name cleared in one building and annotated in the other.",
    "The split is survivable and instructive: the registry's answer can still be sought through reconsideration and the courts (23 Pa.C.S. § 6341(g) — reconsideration within 15 days of the mailing date; appeal within 30 days), clocks that run from mailing, not from the day the letter is opened. The corridor stays open. It is just longer than it needed to be."],
    ending=True, debrief=[
      "THE SPLIT, AND THE DOOR LEFT IN IT — Section 6341(g) keeps a lost Bureau decision reviewable: reconsideration requested within 15 days of the decision's mailing date, and an appeal to the Commonwealth Court within 30 days. Both clocks run from mailing — the library's most unforgiving arithmetic, and the reason decisions are opened the day they arrive in winning households.",
      "WHAT NO STRATEGY CONTROLS — Coin-flip credibility calls, which are why the route refuses them: the exhibits (the agency's own addendum; a clerk's logbook) were built so no officer ever had to choose whose word to take. Abandoning the paper at the closing table re-opens the flip."]),
  N("end_case_only",120,"May 3, Unfiled",[
    "Sunday, May 3, 2026 passes in this branch the way unmarked deadlines do: quietly, on a weekend, while the case — the visible, serviced, reviewed case — proceeds in apparent health. The appeal window closes on a registry entry that will outlive the dependency case by years.",
    "The case itself closes in the fall, a genuine success. The registry surfaces afterward, in clearance renewals, in the district's annual paperwork — a footnote with a man's name on it, renewed annually, appealable no longer. The two-column board exists to prevent exactly this: the healthy file hiding the expiring one."],
    ending=True, debrief=[
      "THE PERISHABLE, UNPRESERVED — Notified February 2, 2026; 90 days → Sunday, May 3, 2026 (23 Pa.C.S. § 6341(a)(2)). The scenario's central trap is attention: a dependency case generates meetings, services, and paper weekly, while an appeal generates one deadline and silence. Everything urgent feels like the case. The appeal was the only item in either file that could not be continued, cured, or re-filed.",
      "WHAT NO STRATEGY CONTROLS — Nothing in this ending was weather. The window was known, dated, and drawn on the board in the route's first scene. Sequence is the strategy; this is the control case that proves it."]),
 ],
 strategy=dict(
  win_honest="This is a **full** win — both proceedings closed completely, registry expunged and case closed in the same season. It is achievable here because the facts permitted it: the decisive documents (a superintendent's logbook, an intake note, the agency's own correction) existed from the start. The capstone skill is separation: two burdens, two packets, one corridor walked in both directions.",
  law=[
   "**Two proceedings, two burdens, never merged.** The Bureau appeal turns on the agency's burden — substantial evidence that the report should remain indicated (23 Pa.C.S. § 6341(c.2)(5)) — while the dependency case turns on the plan and the child's needs under its own review structure. The scenario's board (APPEAL | CASE) is the strategy in one image.",
   "**Perishable first, again.** Notified February 2, 2026, the § 6341(a)(2) window closed Sunday, May 3, 2026 — a weekend, unmarked by any meeting. It is filed on day 10 precisely because the case's weekly noise is designed by the calendar to drown it.",
   "**Decisive paper is usually already written.** The logbook (two calls, 9:04 and 11:47) surfaces through the dependency record request (§ 3130.44(d))'s cross-reference; the intake note through the appeal's evidence rule (§ 6341(c.2)(4)); the agency's correction addendum then defeats its own summary from inside its own file — Exhibit 1 by the route's deliberate ordering.",
   "**Decisions are carried, not announced.** The expungement order is filed into the dependency record the week it issues; the fall packet is built monthly and filed early; counsel (42 Pa.C.S. § 6337) enforces the separation to the last review. The loss branch preserves § 6341(g)'s clocks — reconsideration 15 days from mailing, Commonwealth Court 30 days — for completeness."],
  traps=[
   ("Focusing on the case and letting the appeal 'wait for spring' at *Appeal Week*","the case can be continued; the window cannot. That choice is the direct road to **May 3, Unfiled**."),
   ("Closing the Bureau hearing on the father's credibility instead of the exhibits","credibility is a coin flip; the addendum is a white flag. The flip is the road to the split ending — and its § 6341(g) clocks run from mailing."),
   ("Keeping the logbook as a hearing surprise","the agency committed to its summary in writing months earlier; filed paper testifies in both tracks for months, surprises for eleven minutes."),
   ("Assuming the fall review will 'hear about' the expungement","reviews read files. The corridor is walked by the parent, order in hand, or it is not walked.")],
  uncontrolled="The hearing officer, the superintendent's habits, the furnace. The route controlled separation, sequencing, and the summoning of documents — in a two-proceeding case, the whole of the controllable."),
)

# ---------------- S135 — Complex ----------------
S135 = dict(
 num=135, name="Four Seasons", tier="Complex",
 startDateISO="2025-09-01", startCash=190,
 summary="Three children enter care in a single September — two on the first, a third four weeks later — and the case runs the full wheel of the year: four seasons of services, reviews, and documentation, ending at a permanency hearing where the question is whether the goal itself survives.",
 contentNote="This scenario depicts a long-running dependency case spanning a full year. There is no graphic content. Players may skip any scene or use the quick exit at any time.",
 offsetNote=" (the elder children's foster-care entry date)",
 win_id="end_goal_survives",
 nodes=[
  N("start",0,"September, Three Times",[
    "Your name is Yolanda. Esteban, twelve, and Paloma, nine, entered care on Monday, September 1, 2025 — the housing collapse arriving, as it does, on a holiday weekend, when the landlord's deadline met the shelter's waitlist and the children's school-year start met both. Nico, five, entered four weeks later, on Monday, September 29, after his brief kinship stay with your cousin failed on her own emergency surgery.",
    "Three children, two entry dates, one mother, and a case that will run the full wheel of the year: their fifteenth months land on Tuesday, December 1, 2026 (the elders) and Tuesday, December 29, 2026 (Nico) — dates so far away in this September that they feel theoretical. They are not theoretical. They are the case. Your lawyer, Ms. Ferreira, writes both dates on the folder before she writes anything else."],
    [C("Start the compendium now: one binder, three sections, every date from day one","compendium_start",flags=["compendiumStarted"],hidden="Year compendium begun on day one, three sections",note="A year this long cannot be reconstructed next fall. It can only be kept."),
     C("A binder is premature — get through the first month first","compendium_start",note="The first month is exactly the part nobody can reconstruct later. The binder is the memory.")]),
  N("compendium_start",6,"Ms. Ferreira's Wheel",[
    "She draws the year as a wheel — four seasons, each with its work: FALL, stabilize and document; WINTER, cure the plan's gaps in writing; SPRING, build the housing answer; SUMMER, assemble the exceptions before anyone asks for them. Counsel is your right (42 Pa.C.S. § 6337); here counsel is also a calendar with a philosophy.",
    "'Permanency hearings are not won in the fall of the second year,' she says. 'They are won in the fall of the first, by people who knew the second fall was coming.'"],
    PAPER("fall_services")),
  N("fall_services",20,"Fall: The Services Begin",[
    "The plan's services begin their slow enrollment: parenting program (October start), family therapy (November, after the provider's waitlist), housing case management (immediate, and immediately a waiting game). Each enrollment — and each wait — is a dated fact, and the compendium's first discipline is to record waits as facts rather than as blanks.",
    "A wait recorded is a gap owned by its true owner later. A wait unrecorded becomes, in the retelling, a parent who did nothing in October."],
    [C("Log every enrollment and every waitlist date in the compendium, monthly","fall_visits",flags=["waitsLogged"],hidden="Service enrollment and waitlist dates logged from the first month",note="Waits, logged, belong to the system. Waits unlogged belong to you."),
     C("The providers keep records — that's enough","fall_visits",note="Providers keep records of attendance. Waits live in your file or nowhere.")]),
  N("fall_visits",41,"Fall: The Visits Find Their Rhythm",[
    "Visits settle at the family center: Esteban's laconic twelve-year-old audits, Paloma's art output (filed copies, originals to the children), Nico's kindergarten reports relayed by his foster mother with a generosity the compendium notes by name.",
    "Three children in two placements generate two visit structures, two sets of notes, one exhausted mother, and — if she keeps it — one binder where both structures are reconciled monthly. Reconciliation is the compendium's second discipline: contradictions found in November are cheap; found next October, they are cross-examination."],
    [C("Reconcile both placements' notes into the compendium monthly","winter_gap",flags=["notesReconciled"],hidden="Both placements' visit notes reconciled monthly in the compendium",note="One binder, two placements, no contradictions left to ripen."),
     C("Each placement's notes are its own file's business","winter_gap",note="Until one hearing reads both files, and asks why they disagree about you.")]),
  N("winter_gap",76,"Winter: The Therapy Gap",[
    "The family-therapy referral — signed in the plan in October — is actually sent in January, an eleven-week gap the record, read carefully, attributes to a staffing vacancy and a queue. The compendium has the plan's date and the referral's date on facing pages, where they have been accusing each other quietly since November.",
    "Services identified in the plan but not provided are one of the permanency clock's own exceptions (42 U.S.C. § 675(5)(E)) — but only when they are documented as such, in the case plan, in time. A gap with dates is an exception. A gap with adjectives is an argument."],
    [C("Write the gap letter: plan date, referral date, vacancy — filed, with both dates attached","gap_letter135",cash=-5,flags=["gapDocumented"],hidden="Therapy referral gap documented in writing with both dates",note="Eleven weeks, owned by their true dates. The exception's first brick."),
     C("Raise the gap at the winter review so the judge hears it live","gap_letter135",note="Judges hear many things live. They rely on what is filed.")]),
  N("gap_letter135",90,"Winter: The Record, Requested",[
    "You request the case record in writing (55 Pa. Code § 3130.44(d)) — the mid-winter mirror check the compendium exists to survive: does the file's version of the fall match the binder's? Mostly, yes. Where it doesn't — a visit marked supervised that wasn't, a wait omitted — the corrections are filed as pages, not complaints.",
    "Redactions under (f) black out the cousin's medical details, as the rule provides. The mirror is partial by design. The binder is not."],
    [C("File the corrections as dated pages and index the mirror against the binder","winter_review135",flags=["recordsRequested"],hidden="Case record requested under § 3130.44(d); corrections filed as dated pages",note="The mirror and the binder, reconciled. Next fall's hearing will meet one story, in two bindings."),
     C("Note the discrepancies for counsel to raise later","winter_review135",note="Later is where discrepancies go to become 'inconsistencies in the mother's account.' File them.")]),
  N("winter_review135",120,"Winter: The Review",[
    "The winter review is the wheel's first checkpoint: services running, gap documented, housing the open wound — your applications are a sheaf of waitlist letters, each dated, each a small proof that the wound is the market's and not the mother's.",
    "The judge continues the goal and says the sentence that will be quoted in the fall: 'Housing is the case. Everything else is commentary.' The compendium records the sentence, dated. Sentences judges say in winter have a way of being load-bearing in autumn."],
    PAPER("spring_housing")),
  N("spring_housing",168,"Spring: The Housing Answer",[
    "The housing answer arrives the way housing answers do: not an apartment, but a letter — the housing authority's dated projection, your case manager's confirmation, and a landlord's conditional commitment for a three-bedroom in the children's school zone, contingent on the fall voucher round.",
    "A projection is not a home. But a dated, letterheaded, contingently-committed answer is the difference between a plan and a hope — and reviews, permanency hearings especially, are machines for telling those apart."],
    [C("Get every element in writing, on letterhead, dated — and file them together","housing_letter135",cash=-5,flags=["housingLetter"],hidden="Housing answer assembled in writing: projection, confirmation, landlord commitment",note="Three letters, one answer. The wound now has a documented treatment plan."),
     C("The case manager's word is solid — paper can follow","housing_letter135",note="Words are solid until staff rotate. Paper is the only staff that never rotates.")]),
  N("housing_letter135",196,"Spring: The Children's Pages",[
    "Spring adds the children's own pages to the compendium: Esteban's school letter (attendance, the honor roll's second quarter, a counselor's line about a boy 'carrying his family like a job'), Paloma's art teacher's note, Nico's foster mother's spring letter — the chorus, collected while it is singing, not reconstructed after.",
    "None of these pages was requested by any proceeding. All of them will be read by one."],
    [C("File the children's pages in the compendium and the case record","spring_review135",flags=["chorusFiled"],hidden="Children's school and caregiver pages collected and filed",note="The chorus, in writing, in season. Fall will not have to imagine them."),
     C("School letters can be gathered in the fall if needed","spring_review135",note="Fall-gathered letters describe last spring from memory. Collect in season.")]),
  N("spring_review135",232,"Spring: The Review",[
    "The spring review is the first where the file and the binder fully agree, because for two seasons you have been making them agree monthly. The agency's report uses the phrase 'documented progress' four times. The goal continues; the permanency hearing is set for the fall — the wheel's last quarter, where the December dates will finally be close enough to cast shadows.",
    "Ms. Ferreira opens the compendium to its last section, still mostly empty, labeled in her hand: EXCEPTIONS — TO BE BUILT BEFORE ASKED."],
    PAPER("summer_a")),
  N("summer_a",262,"Summer: The Exceptions, Built",[
    "Summer's work is the section's: exception one, relative care — considered and documented (the cousin's post-surgery capacity, assessed in writing and honestly insufficient for three; the assessment itself is the evidence the exception was examined, not assumed). Exception two, the case-plan compelling reason — reunification on a documented trajectory, the housing answer dated, the trial return proposed for the fall. Exception three, services not provided — the therapy gap, already lettered in the winter.",
    "Exceptions are not arguments to be invented at the hearing. They are sections to be built in the summer, from the year's own pages."],
    [C("Assemble the exception section child by child, each with its own dates","summer_b",cash=-10,flags=["exceptionsBuilt"],hidden="Exception section assembled per child from the year's documentation",note="Three exceptions, three children, nine dated subsections. Built before asked."),
     C("Build one family exception narrative — the story is unified","summer_b",note="Stories unify; clocks don't. The statute will count the children separately, and so must the binder.")]),
  N("summer_b",290,"Summer: The Trial Begins",[
    "The trial return begins in August on the compendium's own proposal: weekends becoming weeks, the placements converting to the family's documented support, school enrollment in the home zone completed in August rather than scrambled in October.",
    "Three children come home in stages the binder has rehearsed on paper since spring. The stages are not the win — the hearing still stands between this family and permanence — but they are the hearing's best evidence, generated by living rather than by argument."],
    [C("Document the trial's stages in the compendium as they happen","fall135",flags=["trialDocumented"],hidden="Trial return stages documented in the compendium",note="The trial, logged like the year was: as it happens, in ink."),
     C("Live the trial; the file has enough paper","fall135",note="The file's appetite is the one constant of the year. Feed the trial too.")]),
  N("fall135",365,"The Second Fall",[
    "A year after the first September, the wheel completes its turn: the elder children's fifteenth month is eight weeks out (Tuesday, December 1, 2026), Nico's twelve (Tuesday, December 29). The agency's permanency position lands in writing: it will ask the court to consider the goal — language that means the filing question and the goal question will be heard together, at a hearing now set for late October.",
    "Families who built the exceptions section in the summer read that letter as a scheduling notice. Families who didn't, read it as a verdict. The difference was made in July, at a kitchen table, with a binder."],
    [C("Answer the position in writing: exceptions documented per child, trial running, housing letter attached","goal_hearing135",cash=-5,flags=["positionAnswered"],hidden="Agency permanency position answered in writing with the exception sections",note="Answered in writing, in advance, per child. The hearing is now a reading."),
     C("Wait for the hearing to answer — that's what it's for","end_december",note="Hearings are for deciding. Families who arrive with answers already filed get decided about less."),
     C("Ask for a continuance into December to strengthen the trial record","end_december",note="December is not a neutral month in this case. It is the clock's home address.")]),
  N("goal_hearing135",395,"The Hearing Where the Goal Is the Question",[
    "The hearing is the year's harvest: the agency, to its credit and its file's, states the documented position — the exceptions stand per child, the therapy gap is the plan's own arithmetic, the trial is succeeding on the binder's pages. The goal question is asked anyway, because asking it is the hearing's job, and it is answered by a compendium the court has clearly read.",
    "Your testimony is the year's shortest document: the dates, the waits, the housing letter, the children home. The binder testifies the rest of the way, in three sections and a winter judge's quoted sentence."],
    [C("Ask for the order: goal unchanged, trial to convert, exceptions as documented per child","end_goal_survives",req=["recordsRequested","gapDocumented","compendiumBuilt","housingLetter"],note="Asked with the whole year behind it. The wheel stops where it started: home."),
     C("Accept the agency's compromise: the goal changes for the elders, holds for Nico","end_split135",note="A split goal is a split family with a court date. The binder argued for one family."),
     C("Argue the goal should never have been questioned, at length, from the heart","end_goal_changed",note="Length and heart are not exhibits. The hearing punishes the speech and rewards the binder — and this branch gives it only the speech.")]),
  N("end_goal_survives",410,"The Goal Survives",[
    "The order keeps the goal — reunification — for all three children, adopts the documented exceptions, and converts the trial on schedule. The children are home for the second December in their own rooms, in the school-zone apartment the spring letters promised, the voucher and the landlord and the case manager's paper having converged, as documented things sometimes do, into an address.",
    "State the win the house way: the children spent fifteen months in care, and the second December cannot refund the first. What the year of documentation did was ensure that when the clock finally asked its question, the answer had been assembled in advance, child by child, season by season — and the goal, which is the case's soul, survived its own hearing. Partial, the guides insist, because the year is not refundable. Survived, because everything that could be saved was."],
    ending=True, debrief=[
      "THE CLOCKS, AUDITED PER CHILD — Elders: entered Monday, September 1, 2025 + 15 months = Tuesday, December 1, 2026. Nico: entered Monday, September 29, 2025 + 15 months = Tuesday, December 29, 2026. 42 U.S.C. § 675(5)(E) counts each child separately, which is why the exceptions were built per child: the documented therapy gap (services identified but not provided), the case-plan compelling reason, and relative care honestly assessed. The hearing preceded both dates because the exceptions were assembled in the summer, not argued in December.",
      "WHY PARTIAL IS THE HONEST LABEL — The goal survived, the children are home, the case converts — after fifteen months. The library's guides label outcomes, not efforts: a family that loses a year to a housing market and a staffing vacancy has won the best available outcome and lost a year doing it. Both facts belong in the debrief. The strategy's claim is the narrower one: no part of the year was lost to anything documentable-and-undocumented.",
      "WHAT NO STRATEGY CONTROLS — Housing markets, provider waitlists, a cousin's surgery, and the school-zone map. The route controlled the compendium: waits logged as facts, notes reconciled monthly, gaps lettered in their own season, exceptions built before asked, and a record requested in time to reconcile the mirror (55 Pa. Code § 3130.44(d)). A year-long case is a memory contest. The binder is how a family wins one. Counsel: 42 Pa.C.S. § 6337."]),
  N("end_split135",410,"One Family, Two Goals",[
    "The court's order splits the difference the compromise offered: Nico's goal holds, the elders' converts to a longer plan with a review in the spring. The children remain, mostly, together; the file no longer describes one family with one destination.",
    "Split goals are the permanency system's compromise genre — no one lost, no one finished, another wheel beginning for two of the three children. The binder stays open. It has a second year in it if the case insists, and by now keeping it is simply what this family does in the evenings."],
    ending=True, debrief=[
      "THE SPLIT, NAMED HONESTLY — A partial outcome short of the partial win: the gated route required **recordsRequested**, **gapDocumented**, **compendiumBuilt**, and **housingLetter** standing together at the ask. Compromises accepted at the hearing convert documented strength into divided plans; the file that was built to answer per child was, in the end, answered per child — by the other side.",
      "WHAT NO STRATEGY CONTROLS — A court's instinct for compromise, which no binder abolishes. The strategy's claim is that the family never had to accept the split for lack of an alternative the record supported. Accepting it anyway is a choice the hearing offers every family; the guides merely insist it be recognized as one."]),
  N("end_goal_changed",395,"The Speech Instead of the Binder",[
    "The hearing that gets the speech instead of the compendium ends the way hearings end when advocacy substitutes for evidence: moved, unconvinced, and bound by a record too thin to carry the goal it was asked to save.",
    "The goal changes. The exceptions, unbuilt, are noted as 'not documented in the case plan' — the statute's quietest and most devastating phrase — and the family's true story becomes a footnote in a plan written by someone else. The binder, where it exists in this branch, is a diary. Diaries do not testify."],
    ending=True, debrief=[
      "NOT DOCUMENTED IN THE CASE PLAN — The exceptions under 42 U.S.C. § 675(5)(E) are not rhetorical positions; the compelling-reason exception exists, by the statute's terms, when it is documented in the case plan. The therapy gap was real, the housing answer was real, the trajectory was real — and undocumented reality is the permanency hearing's most common casualty.",
      "WHAT NO STRATEGY CONTROLS — Very little, here, was weather. The year's raw material was identical; only the keeping of it differed. Four seasons is the library's longest argument that documentation is not the paperwork after the work. It is the work."]),
  N("end_december",456,"December 1",[
    "Tuesday, December 1, 2026 arrives in this branch the way the wheel promised: as the elder children's fifteenth month, with the hearing unheld or unanswered and the filing question now the whole case. Nico's date waits four weeks behind his siblings', as it has since the Septembers.",
    "The exceptions exist — they always existed — in the year's events. The litigation of the winter will be about whether they exist in the case plan, in writing, which is the only place the statute reads. The family that lived the exceptions will now have to prove them backward, from memory, at winter prices."],
    ending=True, debrief=[
      "THE DATES, AS PROMISED — September 1, 2025 + 15 months = Tuesday, December 1, 2026 (elders); September 29, 2025 + 15 months = Tuesday, December 29, 2026 (Nico). 42 U.S.C. § 675(5)(E). Nothing about December was a surprise except that it arrived, which is what dates do when their answers are postponed.",
      "WHAT NO STRATEGY CONTROLS — Continuances in the second fall are the clock's home-field advantage. The route's defense was positional: exceptions built in the summer, the position answered in writing, the hearing reached in October with the binder already filed. Postponement is a strategy too — the other side's."]),
 ],
 strategy=dict(
  win_honest="This is a **partial** win, labeled so by the house rule: the goal survives intact for all three children, the exceptions are adopted, the trial converts, the children are home — after fifteen months. The strategy's triumph is documentary and total; the year is nonetheless spent, and the guide refuses to call that anything but partial. It is the best possible outcome the documented situation allows.",
  law=[
   "**Per-child clocks across a wheel of a year.** Elders entered September 1, 2025 → fifteen months Tuesday, December 1, 2026; Nico entered September 29, 2025 → Tuesday, December 29, 2026 (42 U.S.C. § 675(5)(E)). The scenario's length is its lesson: the dates that decide the case are visible from day one, and the strategy is simply a year spent walking toward them with a binder.",
   "**Waits are facts.** The therapy gap (plan October, referral January) becomes the services-not-provided exception only because it was logged monthly and lettered in its own season. Undocumented gaps are charged to the parent; documented ones are charged to their true owner.",
   "**The compelling reason must live in the case plan.** The summer exception section — per child, per exception, each with dates — is the scenario's core mechanic, built *before* the agency's position made it necessary. The record request (§ 3130.44(d)) reconciles the mirror against the binder mid-year, when corrections are still cheap.",
   "**Housing answers are documents.** Projection + confirmation + landlord commitment, dated and filed together, convert the case's open wound into a treatment plan a hearing can adopt. Counsel (42 Pa.C.S. § 6337) supplies the wheel; the parent supplies the keeping."],
  traps=[
   ("Deferring the binder — 'get through the first month first'","the first month is the part no one can reconstruct in month thirteen. The compendium's gate flag (**compendiumBuilt**) is earned by a year of monthly keeping, and the win requires it."),
   ("Raising the therapy gap orally at the winter review","unfiled gaps are attributed to the raiser at the hearing. The letter, with both dates, is the exception's first brick."),
   ("Asking for a December continuance 'to strengthen the record' at *The Second Fall*","December is the clock's address, not a neutral month. That choice walks directly into the December ending."),
   ("Answering the goal question with a speech instead of the compendium","hearings reward binders and punish speeches — the goal-changed ending is the receipt.")],
  uncontrolled="The housing market, the provider's staffing, the cousin's surgery, and a judge's instinct for compromise. The route controlled the keeping: monthly reconciliation, seasonal letters, summer exceptions, and the mirror checked while corrections were cheap."),
)

# ---------------- S136 — Complex ----------------
S136 = dict(
 num=136, name="The Marathon File", tier="Complex",
 startDateISO="2025-06-02", startCash=210,
 summary="The library's hardest scenario: three children on two clocks, an indicated appeal, a cross-county kinship placement, and a services plan with a vendor-shaped hole — a fifteen-month marathon in which every discipline from every earlier scenario is required at once, in the right order.",
 contentNote="This scenario depicts a complex multi-track dependency case with an appeal and a kinship placement in another county. There is no graphic content. Players may skip any scene or use the quick exit at any time.",
 offsetNote=" (the elder child's foster-care entry date)",
 win_id="end_record_wins",
 nodes=[
  N("start",0,"The Longest Folder",[
    "Your name is Francine. Silas, ten, entered care on Monday, June 2, 2025, after the night your blood pressure took you to the emergency room and the neighbor who called the ambulance could not stay past midnight. The twins, August and Vera, three, entered three weeks later — Monday, June 23 — when the hospital kept you for the surgery nobody had scheduled and the emergency kinship plan ran out of emergencies it could absorb.",
    "You come home in July to an empty house and the thickest folder of your life. Your sister Odile, one county over, is already asking the kinship question. And in the folder's first section sits the letter that will outrank everything for ninety days: an indicated report, notice dated Monday, June 30, 2025, its appeal window (23 Pa.C.S. § 6341(a)(2)) closing Sunday, September 28, 2025. Your lawyer, Ms. Castellanos, opens the folder, reads the dates, and says the sentence this scenario is built to honor: 'This is a marathon. We will run it in the order the deadlines expire, not the order the feelings arrive.'"],
    [C("Accept the order: appeal first, kinship second, plan third, clocks always","order136",flags=["orderAccepted"],hidden="Marathon sequencing accepted: deadlines in expiry order",note="Expiry order. The feelings will be attended to — in writing, on schedule."),
     C("The children come first — the paperwork can queue behind them","order136",note="The children are the paperwork's entire subject. Queueing it behind them is how they wait longer.")]),
  N("order136",7,"The Board of Boards",[
    "The board Ms. Castellanos draws covers a full wall of her office: SILAS (entered Jun 2, 2025; fifteen months Wednesday, September 2, 2026), TWINS (entered Jun 23, 2025; fifteen months Wednesday, September 23, 2026), APPEAL (notified Jun 30, 2025; due September 28, 2025), KINSHIP (Odile, cross-county — two counties' paper for one spare room), PLAN (services, with a vendor problem she already suspects). Counsel is your right (42 Pa.C.S. § 6337); in a marathon, counsel is also the course map.",
    "'Every scenario you have lived so far is inside this one,' she says, 'including the ones you haven't lived yet. We do them in order.'"],
    PAPER("appeal136")),
  N("appeal136",11,"Day Eleven",[
    "The appeal goes out on day 11 of 90 — the half-page, the stamped copy, the calendar annotated with the Bureau's future: evidence, hearing, decision. It is deliberately unglamorous. Marathons are not won in the first mile, but they are most often lost there, to the runner who decided the first mile was beneath her.",
    "Odile, watching the envelope go, begins her own folder that evening. The family's paper gene, Ms. Castellanos will later testify socially, is dominant."],
    [C("Mail it, log the Bureau's clocks, and turn to the kinship file","kinship136",cash=-10,flags=["appealFiled"],hidden="Indicated-report appeal filed on day 11 of the window",note="Mile one, run properly. The wall of dates loses its most perishable entry."),
     C("Polish the appeal another week — first filings deserve care","end_registry136",note="Care is a virtue with a deadline. This branch discovers which one wins.")]),
  N("kinship136",21,"Odile's County, Odile's Paper",[
    "The kinship study for a caregiver in another county runs on two counties' rails: her home county's clearances and home study, your children's county's approval and placement paperwork, and a courier's worth of documents that must exist in both files, identical, or be treated as existing in neither.",
    "A child being cared for by a relative stands inside the permanency clock's own exceptions (42 U.S.C. § 675(5)(E)) — but the placement must be real on paper in both counties before it is real in the children's lives. Odile's spare room is forty minutes away and, administratively, in another country."],
    [C("Itemize the cross-county study in writing with both counties' workers, item by item","study136",cash=-5,flags=["studyList"],hidden="Cross-county kinship study itemized in writing with both counties",note="Two counties, one checklist, no item owned by 'the other office.'"),
     C("Let the counties coordinate — that's their machinery","study136",note="Their machinery coordinates the way weather coordinates picnics. Itemize it yourself.")]),
  N("study136",35,"The Plan's Vendor Problem",[
    "Your services plan requires a specialized parenting program with exactly one vendor in the region — whose waitlist, the record will eventually show, ran four months that summer. The plan was signed in July. The enrollment letter is dated November. Between those dates, on the file's face, sits a mother apparently doing nothing.",
    "You are not doing nothing. You are waitlisted, attending everything else, and — if the marathon's discipline holds — generating the dated paper that will later prove whose queue the season belonged to."],
    [C("Get the waitlist position in writing from the vendor, dated, and file it","vendor_letter",cash=-5,flags=["waitlistDocumented"],hidden="Vendor waitlist position documented in writing and filed",note="The queue, in writing, with a date. November's enrollment will read very differently beside July's letter."),
     C("The agency knows about the waitlist — everyone does","vendor_letter",note="Everyone knowing is how it becomes no one's document. Get the letter.")]),
  N("vendor_letter",49,"The Records, All of Them",[
    "The record request goes in writing (55 Pa. Code § 3130.44(d)) — and in this case, there are effectively three records to mirror: Silas's, the twins', and the study file growing one county over. You request what's yours, Odile requests what's hers, and counsel reconciles the three against the board.",
    "What the mirrors show is mostly a system working at its ordinary speed — which is to say, too slowly for childhood, and documenting its own pace as it goes. The pace, documented, becomes the case's most useful exhibit: the services-not-provided exception writes itself out of the agency's own dates, if someone assembles them."],
    [C("Assemble the pace exhibit: plan dates against service dates, per child","pace136",cash=-5,flags=["recordsRequested"],hidden="Case records requested under § 3130.44(d); plan-vs-service pace exhibit assembled",note="Their dates, your assembly. The marathon's central document is a table of the system's own calendar."),
     C("Request Silas's record now and the twins' later","pace136",note="Later is how one child's mirror ends up nine months staler than another's — in a case where the children share a hearing.")]),
  N("pace136",70,"The Appeal's Evidence",[
    "The Bureau's scheduling order triggers the agency's evidence duty: all evidence gathered in the investigation relevant to the determination, including the potentially exculpatory, within ten days (23 Pa.C.S. § 6341(c.2)(4)). The packet includes the ER's discharge timeline and the neighbor's statement — the neighbor who called the ambulance and stayed until midnight, whose account of a medical emergency reads nothing like the summary's 'failure to arrange care.'",
    "The indicated finding was written from the midnight hour forward. The evidence packet preserves the day from the ambulance forward. Hearings are where timelines meet, and earlier usually beats louder."],
    [C("Build the appeal exhibits around the day's timeline: ambulance, ER, neighbor, midnight","exhibits136",flags=["evidenceReceived"],hidden="Investigation evidence obtained under § 6341(c.2)(4); timeline exhibit built",note="A day, in order, from primary paper. The summary's midnight-forward version is about to meet it."),
     C("Your account of that night is the heart of the appeal","exhibits136",note="Your account is the heart. The exhibits are the ribs that keep it standing under cross-examination.")]),
  N("exhibits136",95,"Autumn Reviews",[
    "The autumn reviews — one per docket, back to back — read a family visibly organizing itself: the appeal docketed, the study itemized and advancing on two counties' rails, the plan's everything-but-the-vendor complete or documented, the pace exhibit filed without drama.",
    "Silas's judge delivers the season's sentence: 'The file reads like it is being kept by someone who expects it to be read.' It is the nicest thing a court has ever said about this family, and it is about the paperwork. The marathon accepts the compliment on the paperwork's behalf."],
    PAPER("study_travels")),
  N("study_travels",150,"The Study Completes — and Travels",[
    "Odile's study completes in her county in the new year — and then must travel: certified into the children's county file, accepted, and converted into a placement approval, a journey of stamps that takes the exact number of weeks it takes, which is why the marathon started it in July.",
    "The twins move to Odile's in February — Silas joining them for weekends and then, on the amended plan, for the school term's second half, the sibling group reassembled under one roof for the first time since June. A relative placement, documented in two counties. The clock's exception now has an address."],
    [C("Get the study's acceptance in writing in the children's county file, dated","kin_ready",flags=["kinReady"],hidden="Cross-county kinship study accepted in writing; children placed with kin",note="Accepted, dated, filed in both counties. The exception has an address and a stamp."),
     C("The placement itself proves the study — don't chase the stamp","kin_ready",note="Placements get questioned; stamps answer. Chase the stamp.")]),
  N("kin_ready",263,"The Bureau Hearing",[
    "Friday, February 20, 2026. The agency must carry its burden — substantial evidence that the report should remain indicated (23 Pa.C.S. § 6341(c.2)(5)) — with a summary written from midnight forward, against an appellant's timeline written from the ambulance forward, sourced from its own evidence packet.",
    "The neighbor testifies for nine minutes. The ER timeline is four. The hearing officer asks the agency's witness when the summary's author last read the neighbor's statement, and the transcript preserves a silence of the length that wins appeals."],
    [C("Close on the timeline and the burden: their standard, their packet, your day","appeal_decision136",note="A day in order beats a summary in adjectives. Close on the paper."),
     C("Close on the children and the year this entry has cost them","appeal_decision136",note="True, and not the standard. The officer must apply the standard; give her the paper that satisfies it.")]),
  N("appeal_decision136",285,"Expunged, Mid-Marathon",[
    "The decision — within the 45 days the rule allows (23 Pa.C.S. § 6341(c.3)) — amends the report to unfounded, entered with most of the marathon still to run. The children's-file reader will meet a mother whose report was examined and expunged, because the order will be carried into both dependency files by hand, the way all paper in this family travels: deliberately.",
    "What remains is the permanency year: two clocks (September 2 and September 23, 2026), a kinship placement holding, a vendor's program finally enrolling you in its spring cohort, and a services record whose gaps all have the system's name on them."],
    [C("File the expungement in both children's files with a cover note","spring136",flags=["expungementFiled"],hidden="Expungement order filed in both dependency files",note="Mile twenty, run like mile one. The corridor is the course."),
     C("The courts read each other's outcomes eventually","spring136",note="Eventually is the marathon's enemy in a sash. File it this week.")]),
  N("spring136",300,"Spring: The Vendor's Cohort",[
    "The vendor's program — the plan's last open service — enrolls you in March, eight months after the plan signed for it, with the waitlist letter from July already in the file explaining exactly whose eight months those were. You attend like a woman with a September deadline and a folder to feed: perfectly, documentedly.",
    "Completion lands in June. The certificate is filed beside the waitlist letter, the two documents bookending the plan's longest gap with the system's name on both covers."],
    [C("File the completion beside the waitlist letter — the gap, bookended","packets136",flags=["servicesDone"],hidden="Vendor program completed; certificate filed beside the waitlist letter",note="Bookended. Any future reader meets the explanation before the gap."),
     C("File the certificate alone — completion speaks for itself","packets136",note="Completion speaks. The gap, unbookended, speaks louder.")]),
  N("packets136",350,"The Packets, Per Child",[
    "Summer's assembly: an exception packet per child — Silas's, the twins' (theirs shared where the law shares it, separate where the dates divide) — each holding the relative-care documentation (Odile's approved, accepted, two-county placement), the compelling-reason case-plan language requested in writing, and the pace exhibit's per-child table: services identified, services provided, the difference dated and owned.",
    "Three packets, two clocks, one hearing season. The marathon's last miles are run at a desk, which is where marathons in this library are always actually run."],
    [C("File the packets and the case-plan language request together, per child","plan_entries136",cash=-10,flags=["packetBuilt"],hidden="Per-child exception packets assembled; compelling-reason plan language requested",note="Per child, in writing, in the plan. The statute reads plans; the packets make sure the plans say it."),
     C("One family packet tells the story better","plan_entries136",note="Stories lose to arithmetic at fifteen months. Packets are counted per child because children are.")]),
  N("plan_entries136",385,"The Plan Entries Land",[
    "The case-plan amendments enter in their per-child forms: relative care, noted; compelling reason, written in the plans' own language — reunification trajectory documented, trial return proposed for the late summer; services gaps, recorded with their owners' dates. The exceptions now exist in the only place the statute reads for them.",
    "Ms. Castellanos walks the wall of dates one final time and takes down September 28, 2025's card — the appeal, long resolved — leaving the two September 2026 dates standing. 'Two dates,' she says. 'Three children, two dates, one family. Bring me the summer without a surprise in it.'"],
    [C("Run the summer on the plan: visits expanding at Odile's, trial steps dated","summer136",flags=["planEntered"],hidden="Exception language entered in both children's case plans",note="The plans now say, in writing, what the year has been proving. Summer, run on rails."),
     C("Summer can breathe a little — the heavy paper is done","summer136",note="Summers that breathe produce autumn surprises. The marathon's last miles are still miles.")]),
  N("summer136",420,"The Summer of the Trial",[
    "The trial return runs in stages across the summer: overnights at your home becoming weeks, Odile's converting — on paper, in both counties — from placement to the family's standing kinship support, the children's school enrollment settled in August in your district with her address as the documented backup.",
    "The September dates approach in their order: Silas's fifteenth month on Wednesday, September 2, 2026; the twins' on Wednesday, September 23. Behind each date stands a plan entry, a packet, and a relative's documented home. The clocks will ask their question of a family that has been answering it, in installments, for fifteen months."],
    [C("Propose the final order in writing: exceptions as documented, trial to convert, Odile's support in ink","hearing_prep136",cash=-5,flags=["orderProposed"],hidden="Final order proposed in writing with documented exceptions",note="Proposed, dated, per child. The hearing is a reading the family has already held at its own table."),
     C("File for the vendor's program audit instead — its waitlist deserves a harder look","end_petition136",note="It does — in some other proceeding. Diverting the marathon at mile twenty-five is how petitions get drafted about you instead.")]),
  N("hearing_prep136",450,"The Hearing, Prepared as a Reading",[
    "Preparation is the liturgy one last time: the pace exhibit refreshed, the plan entries certified from both counties, Odile's statement, the children's school pages, the expungement — the whole marathon, indexed, in three packets and one binder.",
    "Ms. Castellanos's final instruction is the course map's first line, returned as a benediction: 'We ran it in the order the deadlines expired. Let the record show it.'"],
    [C("File the hearing binder a week early, in all three dockets","hearing136",flags=["binderFiled"],hidden="Hearing binder filed early in all three dockets",note="Early, everywhere, identical. The reading can begin."),
     C("File it the morning of — the summer's facts are fresh","hearing136",note="Fresh facts, late paper. The court reads what was filed; the morning-of binder is a rumor with a cover.")]),
  N("hearing136",457,"September 2, 2026",[
    "Silas's fifteenth month arrives as a hearing, which is what prepared-for fifteenth months become. The court works the packets: relative care, documented in two counties; the compelling reason, in the plans' own entries; the services pace, tabled from the agency's own dates — the exception for services identified but not provided, proved by the system's calendar rather than the mother's adjectives (42 U.S.C. § 675(5)(E)).",
    "The filing question is asked and answered in the same hour, for Silas — and, the court notes for the record, the same documentation stands ready for the twins' date in three weeks. No petition is filed in any child's case. The goal never moved."],
    [C("Ask for the final orders: trial converted, Odile's support in writing, closure set at the twins' review","end_record_wins",req=["recordsRequested","appealFiled","packetBuilt","kinReady"],note="Asked on the first clock's day, with the second clock's answer already filed. The marathon ends the way it was run."),
     C("Ask for immediate full closure of all three cases today","end_mixed136",note="The twins' clock runs three more weeks; closure today outruns their court's calendar. The best ending takes the dates in order — as it has all along."),
     C("Let the hearing's momentum carry closure without proposing orders","end_mixed136",note="Momentum closes hearings. Orders close cases. Propose them.")]),
  N("end_record_wins",470,"The Record Wins",[
    "At the twins' review, three weeks later, the same orders land in their dockets — the marathon's second finish line crossed with the same binder. By October the children are home outright, Odile's house holds the standing-support clause and a permanent population of spare toothbrushes, and the folder — the longest folder — is closed in your kitchen, by your hand, on an ordinary evening.",
    "State it honestly, the house way, one final time: this is a partial win. Fifteen months of childhood were spent in the system's care, and the expungement cannot unspend them. What the record did — all it ever claimed to do — was ensure that no deadline in any track ever found this family late, undocumented, or unprepared; that every gap carried its true owner's name; and that when the clocks asked their questions, the answers had been filed in advance, per child, in the order the deadlines expired. In the hardest case in the library, that is what winning means."],
    ending=True, debrief=[
      "THE MARATHON, AUDITED — Appeal: notified June 30, 2025; 90 days → Sunday, September 28, 2025 (23 Pa.C.S. § 6341(a)(2)); filed day 11; evidence under (c.2)(4); burden under (c.2)(5); decision within (c.3)'s 45 days. Silas: entered June 2, 2025 + 15 months = Wednesday, September 2, 2026. Twins: entered June 23, 2025 + 15 months = Wednesday, September 23, 2026. Exceptions under 42 U.S.C. § 675(5)(E) — relative care (cross-county, documented in both counties' files), case-plan compelling reason (entered in the plans in writing), services not provided (the pace exhibit, built from the agency's own plan-vs-service dates). Records: 55 Pa. Code § 3130.44(d). Counsel: 42 Pa.C.S. § 6337.",
      "WHY PARTIAL, AT THE LIBRARY'S CEILING — Every track resolved in the family's favor and the children still spent fifteen months placed. The guide's honesty rule peaks here: the marathon was winnable from its first week, the win was achieved in full documentary form — and it remains partial, because the prize was never the months back. It was that the months ended, on the family's terms, at the dates the board predicted in July 2025.",
      "WHAT NO STRATEGY CONTROLS — A blood-pressure emergency, a vendor's waitlist, two counties' stamp queues, and three children's separate experience of the same year. The route controlled order, documentation, and the naming of every gap's true owner. The library's whole curriculum is in this scenario; so is its humility."]),
  N("end_mixed136",470,"Two Finish Lines, One Still Painted",[
    "The marathon ends in installments: Silas's case converts on his date; the twins' requires another review cycle, their orders landing a season later than their brother's, the folder closing in two stages like the case opened.",
    "Nothing was lost that paper protects — no petition filed, the goal intact, the registry clear. The split is a calendar's, not a verdict's: two counties and three dockets ran at their own speeds to the end, and the family's consolation is the marathon's own — every date was met by a family already standing there."],
    ending=True, debrief=[
      "A SPLIT FINISH, NAMED HONESTLY — The gated route required **recordsRequested**, **appealFiled**, **packetBuilt**, and **kinReady** together at the final ask. Multi-docket cases resolve per docket even when they are won as a family; the difference between this ending and the best is a season, measured — as everything in this scenario is measured — in childhood.",
      "WHAT NO STRATEGY CONTROLS — Separate courts' calendars, which no binder synchronizes. The strategy's claim survives intact: no track was ever lost, late, or undocumented. Only the closing was staggered, because closings belong to courts."]),
  N("end_petition136",470,"The Petition Draft",[
    "In this branch, the fifteenth month is met the way unbuilt exceptions invite: with a petition drafted in one child's case and the goal formally in question — the services-not-provided truth still true, but now litigated as an argument instead of read as a plan entry.",
    "The case is not lost; marathon families have recovered from petitions, at the cost of another season of hearings and a winter of proving backward what the summer's packets would have proved forward. The binder, opened again, begins its second year. It is heavier now, and so is everyone carrying it."],
    ending=True, debrief=[
      "FORWARD VS. BACKWARD — The exceptions under 42 U.S.C. § 675(5)(E) decide cases in whichever tense they are documented. Documented forward — plan entries, packets, pace exhibits — they are findings waiting for a signature. Proved backward, they are litigation. Same facts, same statute, different year of a child's life.",
      "WHAT NO STRATEGY CONTROLS — A petition, once filed, has its own clocks and its own weather. The route's entire design was to make the filing question answerable in an hour, in September, from paper already filed. The draft exists in the branch where that design was abandoned at mile twenty-five."]),
  N("end_registry136",120,"The Entry That Outlived the Marathon",[
    "The dependency marathon, in this branch, is run beautifully — kinship, plan, clocks, all of it — and the registry keeps its entry anyway, because the appeal letter spent its window being polished in a drawer, and September 28, 2025 passed on a Sunday, unmarked.",
    "The entry surfaces in the years after: the school-volunteer form, the nursing-aide application Francine had planned for the spring the children came home. The marathon was won. Its first mile had been forfeited in July, before the race was understood to have started."],
    ending=True, debrief=[
      "MILE ONE — Notified Monday, June 30, 2025; 90 days → Sunday, September 28, 2025 (23 Pa.C.S. § 6341(a)(2)). Every other element of this scenario can be recovered, continued, re-documented, or cured. The appeal window cannot. The library repeats the lesson at every tier because the system repeats the trap at every scale: the smallest, quietest, earliest deadline is the one that outlives the case.",
      "WHAT NO STRATEGY CONTROLS — Nothing failed here except eleven days' worth of sequencing. That is the point of carving it on the marathon's trophy: in the longest case in the library, the decisive act took ten minutes in the second week."]),
 ],
 strategy=dict(
  win_honest="This is a **partial** win — the library's ceiling outcome, labeled by the house rule: every track resolves for the family (appeal expunged, exceptions adopted per child, no petition filed, children home, kinship support in writing) and the children still spent fifteen months in care. The guide claims documentary totality, not time travel: no clock ever found this family unprepared, and that is the most any strategy in this library has ever promised.",
  law=[
   "**Expiry order is the master rule.** The appeal (notified June 30, 2025 → Sunday, September 28, 2025, 23 Pa.C.S. § 6341(a)(2)) is filed day 11, before the kinship study, before the plan's battles — because it is the only item in the file that cannot be continued, cured, or re-filed. The marathon's two permanency dates — Silas, June 2, 2025 + 15 = Wednesday, September 2, 2026; twins, June 23, 2025 + 15 = Wednesday, September 23, 2026 (42 U.S.C. § 675(5)(E)) — are managed per child from the first week's board.",
   "**Cross-county kinship is paper in duplicate.** The relative-care exception exists only when the placement is documented in the children's county file — a study completed in one county and accepted, in writing, in the other. Identical paper in both files, or the exception is an address, not a fact.",
   "**The pace exhibit converts the services gap.** The vendor's eight-month waitlist becomes the services-not-provided exception through assembly: plan dates against service dates, per child, from the agency's own records (requested under 55 Pa. Code § 3130.44(d)), with the compelling-reason language requested for the plans themselves — the only place the statute reads for it.",
   "**The appeal runs on the shared machinery, at marathon weight:** evidence including the exculpatory under § 6341(c.2)(4), the agency's burden under (c.2)(5), the decision inside (c.3)'s 45 days, counsel (42 Pa.C.S. § 6337) drawing the board of boards."],
  traps=[
   ("Polishing the appeal past its window at *Day Eleven*","the marathon's decisive act takes ten minutes in week two. Its loss is the one ending no later excellence can repair (**The Entry That Outlived the Marathon**)."),
   ("Letting the counties 'coordinate' the kinship study themselves","unitemized cross-county paper exists in neither file. The win's gate requires **kinReady** — an acceptance, in writing, in the children's county."),
   ("Building one family packet instead of per-child packets","the clocks are per child (Sept 2 vs. Sept 23); blended packets blur the exact dates each exception stands on."),
   ("Diverting the summer into auditing the vendor instead of proposing the final order","mile-twenty-five diversions are how the filing question ripens into **The Petition Draft**.")],
  uncontrolled="The medical emergency that opened the case, a vendor's queue, two counties' stamp speeds, and three children's separate years. The route controlled order, documentation, and ownership of every gap — the marathon's whole controllable course."),
)
